import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { CAIRN_KINDS, CHALLENGE_STATUSES, LAB_RUN_STATUSES, LEG_KINDS, POSTMORTEM_TAGS, RELAY_STATUSES, REVIEW_SCORE_MAX, SEVERITIES } from "./lab.js";

// The runtime lists must match the API's OpenAPI document (regenerated by `pnpm sdk`), in order.
const openapi = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as {
  components: { schemas: Record<string, { properties: Record<string, { enum?: string[]; items?: { enum?: string[] } }> }> };
};
const schemas = openapi.components.schemas;

describe("Lab lists", () => {
  it("match the OpenAPI enums", () => {
    expect([...POSTMORTEM_TAGS]).toEqual(schemas.Postmortem!.properties.tags!.items!.enum);
    expect([...SEVERITIES]).toEqual(schemas.Postmortem!.properties.severity!.enum);
    expect([...CAIRN_KINDS]).toEqual(schemas.Cairn!.properties.kind!.enum);
    expect([...CHALLENGE_STATUSES]).toEqual(schemas.LabChallenge!.properties.status!.enum);
    expect([...LEG_KINDS]).toEqual(schemas.LabRelayLeg!.properties.kind!.enum);
    expect([...RELAY_STATUSES]).toEqual(schemas.LabRelay!.properties.status!.enum);
    expect([...LAB_RUN_STATUSES]).toEqual(schemas.LabRun!.properties.status!.enum);
  });

  it("match the review scale the API states", () => {
    const scores = (schemas.LabReview!.properties.scores as unknown as { additionalProperties: { maximum: number } }).additionalProperties;
    expect(scores.maximum).toBe(REVIEW_SCORE_MAX);
  });
});
